LIMIT 1

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel WHERE {
  # directors and birthdates for each film
  dbr:Krush_Groove dbo:director ?dir1 .
  OPTIONAL { ?dir1 dbo:birthDate ?bd1 . }
  OPTIONAL { ?dir1 dbp:birth_date ?bd1b . }
  BIND(IF(BOUND(?bd1), ?bd1, ?bd1b) AS ?birth1)

  dbr:West_of_Sonora dbo:director ?dir2 .
  OPTIONAL { ?dir2 dbo:birthDate ?bd2 . }
  OPTIONAL { ?dir2 dbp:birth_date ?bd2b . }
  BIND(IF(BOUND(?bd2), ?bd2, ?bd2b) AS ?birth2)

  # create two possible film rows, each with its director birth as ?filmBirth
  { BIND(dbr:Krush_Groove AS ?film) BIND(?birth1 AS ?filmBirth) }
  UNION
  { BIND(dbr:West_of_Sonora AS ?film) BIND(?birth2 AS ?filmBirth) }

  # ensure both birthdates are present
  FILTER(BOUND(?birth1) && BOUND(?birth2) && BOUND(?filmBirth))

  # keep only the film whose director birth is later (younger)
  FILTER((?film = dbr:Krush_Groove && ?filmBirth > ?birth2) || (?film = dbr:West_of_Sonora && ?filmBirth > ?birth1))

  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(langMatches(lang(?filmLabel), "EN")) }
}
LIMIT 1

